class temperature_Type {
    /* Function Objective: Convert a Fahrenheit text to Celsius
       Input parameters : str_text (string) temperature in Fahrenheit written as text
       Function description: Read the text as a number and convert it to Celsius; text that is not a number gives zero
       Return Value : float temperature in Celsius
       Created By : Programmer A
       Create Date: 2026-09-28
       Revised By:
       Revised Date:
    */
    static float f_Convert_Celsius(String str_text) {
        final float freezingPoint = 32.0f;
        float f_celsius = 0.0f;
        try {
            // read the Fahrenheit value from the text
            float f_fahrenheit = Float.parseFloat(str_text);
            f_celsius = (f_fahrenheit - freezingPoint) * 5.0f / 9.0f;
        } catch (NumberFormatException e) {
            // the text is not a number, keep zero
            f_celsius = 0.0f;
        } finally {
            // nothing to release, the result is ready
            f_celsius = f_celsius + 0.0f;
        }
        return f_celsius;
    }
}
